const rTones = ['#7a3a24','#c9a24c','#a8462b','#1f130d'];
function renderReelCardHTML(r,i){
  return `<div class="reel-card" data-idx="${i}">
    <div class="reel-bg" style="background:linear-gradient(200deg, ${rTones[i%rTones.length]}, #0a0705);"></div>
    <div class="reel-overlay"></div>
    <div class="reel-stats">▶ ${r.views}</div>
    <div class="reel-play">▶</div>
    <div class="reel-info"><strong>${r.name}</strong><span>${r.creator} · ${r.loc}</span></div>
  </div>`;
}
/* Wires up play-on-click for reel cards rendered by renderReelCardHTML()
   into `container`. `reelList` must be the same array (or slice, taken
   from the start) used to render them, so indices line up. */
function initReelPlayback(container, reelList){
  const bind = (card)=>{
    const r = reelList[Number(card.dataset.idx)];
    const playBtn = card.querySelector('.reel-play');
    if(!r || !playBtn) return;
    playBtn.onclick = ()=>{
      /* only one reel plays at a time: every other open player goes back to its cover */
      container.querySelectorAll('.reel-card').forEach(other=>{
        if(other === card || !other.querySelector('iframe')) return;
        const oi = Number(other.dataset.idx);
        const tmp = document.createElement('div');
        tmp.innerHTML = renderReelCardHTML(reelList[oi], oi);
        other.innerHTML = tmp.firstElementChild.innerHTML;
        bind(other);
      });
      if(r.youtubeId){
        card.innerHTML = `<iframe src="https://www.youtube.com/embed/${r.youtubeId}?autoplay=1" style="position:absolute;inset:0;width:100%;height:100%;border:0;" allow="autoplay; encrypted-media" allowfullscreen loading="lazy"></iframe>`;
      } else if(r.fb){
        const src = `https://www.facebook.com/plugins/video.php?href=${encodeURIComponent(r.fb)}&show_text=false&autoplay=true&width=220&height=391&mute=0`;
        /* the small ↗ link is the escape hatch: some Facebook videos refuse to be embedded */
        card.innerHTML = `<iframe src="${src}" width="220" height="391" style="position:absolute;inset:0;width:100%;height:100%;border:0;overflow:hidden;" allow="autoplay; encrypted-media; picture-in-picture; web-share" allowfullscreen loading="lazy"></iframe>` +
          `<a class="reel-open" href="${r.fb}" target="_blank" rel="noopener" title="Facebook-এ খুলুন" aria-label="Open on Facebook">↗</a>`;
      } else {
        card.querySelector('.reel-info span').textContent = 'Add a youtubeId or fb URL in reels[] to play this';
      }
    };
  };
  container.querySelectorAll('.reel-card').forEach(bind);
}

/* ---- cover art: thumb file -> cover embedded in the mp3 (ID3v2 APIC) -> icon ---- */
function parseID3Cover(buf){
  const u = new Uint8Array(buf);
  if(u.length < 10 || u[0] !== 0x49 || u[1] !== 0x44 || u[2] !== 0x33) return null;   // "ID3"
  const ver = u[3], flags = u[5];
  const syncsafe = (o)=> (u[o]<<21) | (u[o+1]<<14) | (u[o+2]<<7) | u[o+3];
  const total = 10 + syncsafe(6);
  let p = 10;
  if(flags & 0x40){ p += (ver === 4) ? syncsafe(p) : (4 + ((u[p]<<24)|(u[p+1]<<16)|(u[p+2]<<8)|u[p+3])); }  // extended header
  const end = Math.min(total, u.length);
  while(p + 10 <= end){
    const id = String.fromCharCode(u[p], u[p+1], u[p+2], u[p+3]);
    if(!/^[A-Z0-9]{4}$/.test(id)) break;                                              // padding reached
    const size = (ver === 4) ? syncsafe(p+4) : ((u[p+4]<<24)|(u[p+5]<<16)|(u[p+6]<<8)|u[p+7]);
    const start = p + 10, stop = start + size;
    if(size <= 0 || stop > u.length) break;
    if(id === 'APIC'){
      const enc = u[start];
      let q = start + 1, mime = '';
      while(q < stop && u[q] !== 0) mime += String.fromCharCode(u[q++]);
      q++;                                  // end of mime
      q++;                                  // picture type
      if(enc === 1 || enc === 2){           // UTF-16 description: ends with 00 00
        while(q + 1 < stop && !(u[q] === 0 && u[q+1] === 0)) q += 2;
        q += 2;
      } else {                              // latin1 / utf-8 description: ends with 00
        while(q < stop && u[q] !== 0) q++;
        q++;
      }
      if(q >= stop) return null;
      if(!/^image\//i.test(mime)) mime = (u[q] === 0x89) ? 'image/png' : 'image/jpeg';
      return new Blob([u.slice(q, stop)], {type: mime});
    }
    p = stop;
  }
  return null;
}
async function embeddedCover(src){
  try{
    const head = await fetch(src, {headers:{Range:'bytes=0-9'}});
    if(head.status !== 206) return null;                      // server ignores Range -> don't download the whole mp3
    const h = new Uint8Array(await head.arrayBuffer());
    if(h[0] !== 0x49 || h[1] !== 0x44 || h[2] !== 0x33) return null;
    const size = 10 + ((h[6]<<21) | (h[7]<<14) | (h[8]<<7) | h[9]);
    if(size > 6 * 1024 * 1024) return null;
    const body = await fetch(src, {headers:{Range:'bytes=0-' + (size - 1)}});
    if(body.status !== 206) return null;
    const blob = parseID3Cover(await body.arrayBuffer());
    return blob ? URL.createObjectURL(blob) : null;
  }catch(e){ return null; }
}
function resolveCover(t){
  if(t._coverPromise) return t._coverPromise;
  const tryImg = (url)=> new Promise(res=>{
    if(!url) return res(null);
    const im = new Image();
    im.onload = ()=> res(url);
    im.onerror = ()=> res(null);
    im.src = url;
  });
  t._coverPromise = tryImg(t.thumb).then(u=> u || embeddedCover(t.src));
  return t._coverPromise;
}
/* puts the cover into `box` (keeps the music icon until/unless a cover is found) */
function paintCover(box, t){
  box.dataset.src = t.src;
  box.innerHTML = '<i class="fa-solid fa-music"></i>';
  resolveCover(t).then(url=>{
    if(!url || box.dataset.src !== t.src) return;
    const im = document.createElement('img');
    im.src = url; im.alt = '';
    box.innerHTML = '';
    box.appendChild(im);
  });
}

function initSoundPlayer(limit){
  limit = limit || tracks.length;
  const $ = (id)=> document.getElementById(id);
  const soundList = $('soundList'), miniPlayer = $('miniPlayer');
  const miniPlayBtn = $('miniPlayBtn'), miniPrevBtn = $('miniPrevBtn'), miniNextBtn = $('miniNextBtn');
  const miniTrackName = $('miniTrackName'), miniTrackArtist = $('miniTrackArtist');
  const miniBar = $('miniBar'), miniBarFill = miniBar.querySelector('i');
  const mpCurrentTime = $('mpCurrentTime'), mpDuration = $('mpDuration'), mpCatLabel = $('mpCatLabel'), mpArt = $('mpArt');
  const miniShuffleBtn = $('miniShuffle'), miniRepeatBtn = $('miniRepeat'), miniListToggle = $('miniListToggle');
  const playlistOverlay = $('playlistOverlay'), playlistRows = $('playlistRows');
  const playlistTabs = $('playlistTabs'), playlistDesc = $('playlistDesc');

  const audioPlayer = new Audio();
  window.pujaAudioPlayer = audioPlayer;
  const FIRST_LIST = playlists[0].id;
  const listOf = (i)=> tracks[i].list || FIRST_LIST;
  const queueOf = (listId)=> tracks.map((t,i)=>i).filter(i=> listOf(i) === listId);

  let cur = null, shuffleOn = false, repeatOn = false, viewList = FIRST_LIST;
  const rows = [];      // inline list rows, same index as tracks[]
  const plRows = {};    // playlist-panel rows, by track index

  const fmtTime = (sec)=>{
    if(!isFinite(sec) || sec < 0) sec = 0;
    return Math.floor(sec/60) + ':' + Math.floor(sec%60).toString().padStart(2,'0');
  };
  const setPlayIcon = (playing)=>{
    miniPlayBtn.innerHTML = '<i class="fa-solid ' + (playing ? 'fa-pause' : 'fa-play') + '"></i>';
  };
  function markPlaying(){
    rows.forEach((r,i)=>{
      if(!r) return;
      r.row.classList.toggle('playing', i === cur);
      r.play.textContent = (i === cur && !audioPlayer.paused) ? '❚❚' : '▶';
    });
    Object.keys(plRows).forEach(k=> plRows[k].classList.toggle('playing', Number(k) === cur));
  }

  /* ---------- playlist panel ---------- */
  function renderPlaylist(){
    playlistTabs.innerHTML = '';
    playlists.forEach(pl=>{
      const b = document.createElement('button');
      b.type = 'button';
      b.className = 'pl-tab' + (pl.id === viewList ? ' active' : '');
      b.textContent = pl.name;
      b.onclick = ()=>{ viewList = pl.id; renderPlaylist(); };
      playlistTabs.appendChild(b);
    });
    const info = playlists.find(p=> p.id === viewList) || playlists[0];
    playlistDesc.textContent = info.desc || '';
    playlistRows.innerHTML = '';
    Object.keys(plRows).forEach(k=> delete plRows[k]);
    const q = queueOf(viewList);
    if(!q.length){
      const e = document.createElement('div');
      e.className = 'pl-empty';
      e.textContent = 'এই প্লেলিস্টে এখনো কোনো ট্র্যাক নেই — শীঘ্রই যুক্ত হবে';
      playlistRows.appendChild(e);
      return;
    }
    q.forEach((i, n)=>{
      const t = tracks[i];
      const row = document.createElement('div');
      row.className = 'playlist-row' + (i === cur ? ' playing' : '');
      const idx = document.createElement('span'); idx.className = 'pl-index'; idx.textContent = String(n+1).padStart(2,'0');
      const art = document.createElement('div');  art.className = 'pl-art';
      const meta = document.createElement('div'); meta.className = 'pl-meta';
      meta.innerHTML = '<strong>' + escapeHtml(t.name) + '</strong><span>' + escapeHtml(t.artist) + '</span>';
      const dur = document.createElement('span'); dur.className = 'pl-dur'; dur.textContent = t.dur || '';
      row.appendChild(idx); row.appendChild(art); row.appendChild(meta); row.appendChild(dur);
      row.onclick = ()=>{
        if(cur === i && !audioPlayer.paused) audioPlayer.pause();
        else playTrack(i);
      };
      playlistRows.appendChild(row);
      plRows[i] = row;
      paintCover(art, t);
    });
  }

  /* ---------- playback ---------- */
  function loadTrack(i){
    cur = i;
    const t = tracks[i];
    audioPlayer.src = t.src;
    miniTrackName.textContent   = t.name;
    miniTrackArtist.textContent = t.artist;
    mpCatLabel.textContent      = t.cat || 'Puja Sounds';
    miniBarFill.style.width = '0%';
    mpCurrentTime.textContent = '0:00';
    mpDuration.textContent = t.dur || '0:00';
    miniPlayer.classList.add('show');
    paintCover(mpArt, t);
    if(viewList !== listOf(i)){ viewList = listOf(i); renderPlaylist(); }
    markPlaying();
    if('mediaSession' in navigator && window.MediaMetadata){
      resolveCover(t).then(url=>{
        if(cur !== i) return;
        navigator.mediaSession.metadata = new MediaMetadata({
          title: t.name, artist: t.artist, album: 'চট্টলার পুজো',
          artwork: url ? [{src: url}] : []
        });
      });
    }
  }
  function playTrack(i){
    if(cur !== i) loadTrack(i);
    const p = audioPlayer.play();
    if(p && p.catch) p.catch(()=>{});
  }
  function pickNextIndex(dir){
    if(cur === null) return queueOf(viewList)[0] ?? 0;
    const q = queueOf(listOf(cur));
    if(q.length <= 1) return cur;
    if(shuffleOn){
      let i;
      do{ i = q[Math.floor(Math.random() * q.length)]; } while(i === cur);
      return i;
    }
    return q[(q.indexOf(cur) + dir + q.length) % q.length];
  }

  /* ---------- inline list (cover + title + duration) ---------- */
  tracks.forEach((t, i)=>{
    if(i >= limit) return;
    const row = document.createElement('div');
    row.className = 'sound-row';
    const art = document.createElement('div');   art.className = 'sr-art';
    const img = document.createElement('span');  img.className = 'sr-img';
    const play = document.createElement('div');  play.className = 'play'; play.textContent = '▶';
    art.appendChild(img); art.appendChild(play);
    const meta = document.createElement('div');  meta.className = 'meta';
    meta.innerHTML = '<strong>' + escapeHtml(t.name) + '</strong><span>' + escapeHtml(t.artist) + '</span>';
    const dur = document.createElement('div');   dur.className = 'dur'; dur.textContent = t.dur || '';
    row.appendChild(art); row.appendChild(meta); row.appendChild(dur);
    row.dataset.cat = t.cat || '';
    row.onclick = ()=>{
      if(cur === i && !audioPlayer.paused) audioPlayer.pause();
      else playTrack(i);
    };
    soundList.appendChild(row);
    rows[i] = {row, play};
    paintCover(img, t);
  });

  /* category chips (All / Dhak / Shankh / Aarti …) filter the inline list */
  const chips = document.querySelectorAll('.sound-cats .sound-chip');
  chips.forEach(chip=>{
    chip.style.cursor = 'pointer';
    chip.onclick = ()=>{
      chips.forEach(c=> c.classList.remove('active'));
      chip.classList.add('active');
      const want = chip.textContent.trim();
      let shown = 0;
      rows.forEach(r=>{
        if(!r) return;
        const ok = want === 'All' || r.row.dataset.cat === want;
        r.row.style.display = ok ? '' : 'none';
        if(ok) shown++;
      });
      let empty = soundList.querySelector('.sound-empty');
      if(!shown){
        if(!empty){
          empty = document.createElement('div');
          empty.className = 'sound-empty';
          empty.style.cssText = 'padding:22px;text-align:center;color:var(--cream-dim);font-size:0.85rem;';
          soundList.appendChild(empty);
        }
        empty.textContent = want + ' — শীঘ্রই যুক্ত হবে (coming soon)';
      } else if(empty){ empty.remove(); }
    };
  });
  if(chips.length) chips[0].click();

  /* ---------- audio events ---------- */
  audioPlayer.addEventListener('play',  ()=>{ setPlayIcon(true);  markPlaying(); });
  audioPlayer.addEventListener('pause', ()=>{ setPlayIcon(false); markPlaying(); });
  audioPlayer.addEventListener('ended', ()=>{
    miniBarFill.style.width = '0%';
    if(repeatOn) playTrack(cur);
    else playTrack(pickNextIndex(1));
  });
  audioPlayer.addEventListener('loadedmetadata', ()=>{ mpDuration.textContent = fmtTime(audioPlayer.duration); });
  audioPlayer.addEventListener('timeupdate', ()=>{
    if(audioPlayer.duration){
      miniBarFill.style.width = (audioPlayer.currentTime / audioPlayer.duration * 100) + '%';
      mpCurrentTime.textContent = fmtTime(audioPlayer.currentTime);
    }
  });
  miniBar.addEventListener('click', (e)=>{
    if(!audioPlayer.duration) return;
    const rect = miniBar.getBoundingClientRect();
    audioPlayer.currentTime = Math.min(1, Math.max(0, (e.clientX - rect.left) / rect.width)) * audioPlayer.duration;
  });

  /* ---------- controls ---------- */
  miniPlayBtn.onclick = ()=>{
    if(cur === null) return;
    if(audioPlayer.paused){ const p = audioPlayer.play(); if(p && p.catch) p.catch(()=>{}); }
    else audioPlayer.pause();
  };
  miniPrevBtn.onclick = ()=>{ if(cur !== null) playTrack(pickNextIndex(-1)); };
  miniNextBtn.onclick = ()=>{ if(cur !== null) playTrack(pickNextIndex(1)); };
  miniShuffleBtn.onclick = ()=>{ shuffleOn = !shuffleOn; miniShuffleBtn.classList.toggle('active', shuffleOn); };
  miniRepeatBtn.onclick  = ()=>{ repeatOn  = !repeatOn;  miniRepeatBtn.classList.toggle('active', repeatOn); };

  const openList  = ()=>{ renderPlaylist(); playlistOverlay.classList.add('open'); miniListToggle.classList.add('active'); };
  const closeList = ()=>{ playlistOverlay.classList.remove('open'); miniListToggle.classList.remove('active'); };
  miniListToggle.onclick = ()=>{ playlistOverlay.classList.contains('open') ? closeList() : openList(); };
  $('playlistClose').onclick = closeList;
  playlistOverlay.addEventListener('click', (e)=>{ if(e.target === playlistOverlay) closeList(); });
  document.addEventListener('keydown', (e)=>{ if(e.key === 'Escape') closeList(); });
  $('miniClose').onclick = ()=>{
    audioPlayer.pause();
    miniPlayer.classList.remove('show');
    closeList();
  };

  if('mediaSession' in navigator){
    try{
      navigator.mediaSession.setActionHandler('play',  ()=> miniPlayBtn.onclick());
      navigator.mediaSession.setActionHandler('pause', ()=> audioPlayer.pause());
      navigator.mediaSession.setActionHandler('previoustrack', miniPrevBtn.onclick);
      navigator.mediaSession.setActionHandler('nexttrack', miniNextBtn.onclick);
    }catch(e){}
  }
  renderPlaylist();
}

/* ---------- Shared: photo reactions & comments (works on any page) ----------
   Comments open in the shared #commentModalOverlay (see index1.html's modal
   markup) rather than an inline panel — keep that modal + #commentList +
   #commentForm + #commentModalTitle present on any page that uses this. */
function escapeHtml(str){
  return String(str).replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}
async function getReactions(id){
  try{
    const r = await window.storage.get('reactions:'+id, true);
    return r ? JSON.parse(r.value) : {likes:0, comments:[]};
  }catch(e){ return {likes:0, comments:[]}; }
}
async function saveReactions(id, data){
  try{ await window.storage.set('reactions:'+id, JSON.stringify(data), true); }catch(e){}
}
function renderReactionCounts(container, id, data){
  const tile = container.querySelector(`.tile[data-id="${id}"]`);
  if(!tile) return;
  tile.querySelector('.like-count').textContent = data.likes || 0;
  tile.querySelector('.comment-count').textContent = (data.comments||[]).length;
}
function openLightbox(src){
  const box = document.createElement('div');
  box.style.cssText = 'position:fixed;inset:0;z-index:600;background:rgba(5,3,2,0.92);display:flex;align-items:center;justify-content:center;padding:24px;cursor:zoom-out;';
  box.innerHTML = `<img src="${src}" style="max-width:90vw;max-height:88vh;border-radius:10px;box-shadow:0 20px 60px rgba(0,0,0,0.6);">`;
  box.addEventListener('click', ()=> box.remove());
  document.body.appendChild(box);
}

/* ---------- Generic modal open/close (shared by every .modal-overlay on the page) ---------- */
function openModal(id){ const el = document.getElementById(id); if(el) el.classList.add('open'); }
function closeModal(id){ const el = document.getElementById(id); if(el) el.classList.remove('open'); }
document.querySelectorAll('.modal-close-x').forEach(x=>{
  x.onclick = ()=> closeModal(x.dataset.close);
});
document.querySelectorAll('.modal-overlay').forEach(ov=>{
  ov.addEventListener('click', (e)=>{ if(e.target === ov) ov.classList.remove('open'); });
});

/* ---------- Comment modal (shared across every page with #commentModalOverlay) ---------- */
let activeCommentPhotoId = null;
function renderCommentListInto(el, comments){
  el.innerHTML = comments.length
    ? comments.map(c=>`<div class="comment-item"><strong>${escapeHtml(c.name)}</strong><span>${escapeHtml(c.text)}</span></div>`).join('')
    : '<div class="comment-empty">প্রথম মন্তব্যটি আপনিই করুন।</div>';
}
function openCommentModal(id, caption){
  activeCommentPhotoId = id;
  const title = document.getElementById('commentModalTitle');
  if(title) title.textContent = caption ? `Comments · ${caption}` : 'Comments';
  const listEl = document.getElementById('commentList');
  if(listEl) listEl.innerHTML = '<div class="comment-empty">লোড হচ্ছে...</div>';
  getReactions(id).then(data=>{
    if(listEl) renderCommentListInto(listEl, data.comments || []);
  });
  openModal('commentModalOverlay');
}
document.addEventListener('submit', async (e)=>{
  const form = e.target.closest('#commentForm');
  if(!form || !activeCommentPhotoId) return;
  e.preventDefault();
  const id = activeCommentPhotoId;
  const fd = new FormData(form);
  const name = (fd.get('name')||'').toString().trim().slice(0,40);
  const text = (fd.get('text')||'').toString().trim().slice(0,300);
  if(!name || !text) return;
  const data = await getReactions(id);
  data.comments = data.comments || [];
  data.comments.push({name, text, ts: Date.now()});
  await saveReactions(id, data);
  document.querySelectorAll(`.tile[data-id="${id}"] .comment-count`).forEach(el=> el.textContent = data.comments.length);
  const listEl = document.getElementById('commentList');
  if(listEl) renderCommentListInto(listEl, data.comments);
  form.reset();
  const msg = document.getElementById('commentFormMsg');
  if(msg){ msg.textContent = 'ধন্যবাদ! মন্তব্য যুক্ত হয়েছে।'; setTimeout(()=> msg.textContent = '', 2200); }
});

/* Wires up like/comment/lightbox behaviour for a gallery container that
   was filled with renderPhotoTileHTML() tiles. Call once per page. */
function initGalleryInteractions(container, photoList){
  photoList.forEach((p,i)=>{
    const id = p.id || ('photo-'+i);
    getReactions(id).then(data=>{
      renderReactionCounts(container, id, data);
      if(localStorage.getItem('liked:'+id)){
        const btn = container.querySelector(`.like-btn[data-id="${id}"]`);
        if(btn) btn.classList.add('liked');
      }
    });
  });
  if(container.dataset.galleryBound) return;      // safe to call again when more photos are appended later
  container.dataset.galleryBound = '1';
  container.addEventListener('click', async (e)=>{
    const likeBtn = e.target.closest('.like-btn');
    if(likeBtn){
      const id = likeBtn.dataset.id;
      const likedKey = 'liked:'+id;
      const data = await getReactions(id);
      if(localStorage.getItem(likedKey)){
        data.likes = Math.max(0, (data.likes||0)-1);
        localStorage.removeItem(likedKey);
        likeBtn.classList.remove('liked');
      } else {
        data.likes = (data.likes||0)+1;
        localStorage.setItem(likedKey,'1');
        likeBtn.classList.add('liked');
      }
      await saveReactions(id, data);
      renderReactionCounts(container, id, data);
      return;
    }
    const commentBtn = e.target.closest('.comment-btn');
    if(commentBtn){
      openCommentModal(commentBtn.dataset.id, commentBtn.dataset.cap);
      return;
    }
    if(e.target.closest('.tile-react')) return;
    const tile = e.target.closest('.tile');
    if(tile && tile.dataset.src) openLightbox(tile.dataset.src);
  });
}


