/* =====================================================================
   COMMUNITY PHOTOS — visitors upload, you approve, everyone sees them
   ---------------------------------------------------------------------
   Backend = Supabase (free tier). One-time setup: see supabase-setup.sql.
   Then paste the two values below (Project Settings → API):
       url     →  "Project URL"          e.g. https://abcdxyz.supabase.co
       anonKey →  "anon / publishable" key (safe to be public — the database
                  rules in the .sql file are what protect the data)
   While these are empty the site works exactly as before (email only).
   ===================================================================== */
const COMMUNITY = {
  url: '',
  anonKey: '',
  bucket: 'photos',
  table: 'photos',
  maxSide: 1600,        // uploaded photos are shrunk to this many px on the longest side
  quality: 0.82,
};
const communityEnabled = ()=> !!(COMMUNITY.url && COMMUNITY.anonKey);
function communityHeaders(extra){
  const h = Object.assign({apikey: COMMUNITY.anonKey}, extra || {});
  if(/^eyJ/.test(COMMUNITY.anonKey)) h.Authorization = 'Bearer ' + COMMUNITY.anonKey;   // legacy JWT-style anon key
  return h;
}
const communityImageURL = (path)=> COMMUNITY.url.replace(/\/$/, '') + '/storage/v1/object/public/' + COMMUNITY.bucket + '/' + path.split('/').map(encodeURIComponent).join('/');

/* approved rows -> the same shape as photos[] (text is escaped: it comes from visitors) */
function communityRowToPhoto(row){
  if(!row || !/^[\w\-./]+$/.test(row.image_path || '')) return null;
  const ratio = (row.width && row.height) ? row.height / row.width : 0.8;
  return {
    id: 'cp-' + row.id,
    h: Math.max(170, Math.min(320, Math.round(240 * ratio))),
    cap: escapeHtml(row.caption || ''),
    loc: escapeHtml(row.location || ''),
    credit: escapeHtml(row.credit || ''),
    img: communityImageURL(row.image_path),
    community: true,
  };
}
async function loadCommunityPhotos(limit){
  if(!communityEnabled()) return [];
  try{
    const q = '?select=id,caption,location,credit,image_path,width,height,created_at&status=eq.approved&order=created_at.desc&limit=' + (limit || 200);
    const res = await fetch(COMMUNITY.url.replace(/\/$/, '') + '/rest/v1/' + COMMUNITY.table + q, {headers: communityHeaders()});
    if(!res.ok) throw new Error('HTTP ' + res.status);
    return (await res.json()).map(communityRowToPhoto).filter(Boolean);
  }catch(e){
    console.warn('Community photos could not be loaded:', e);
    return [];
  }
}

/* shrink + re-encode in the browser (phones send 5–10 MB photos) */
async function compressImage(file){
  let bmp;
  try{ bmp = await createImageBitmap(file, {imageOrientation:'from-image'}); }
  catch(e){
    bmp = await new Promise((ok, no)=>{
      const url = URL.createObjectURL(file), im = new Image();
      im.onload = ()=>{ URL.revokeObjectURL(url); ok(im); };
      im.onerror = ()=>{ URL.revokeObjectURL(url); no(new Error('unreadable image')); };
      im.src = url;
    });
  }
  const w0 = bmp.width, h0 = bmp.height;
  const scale = Math.min(1, COMMUNITY.maxSide / Math.max(w0, h0));
  const w = Math.max(1, Math.round(w0 * scale)), h = Math.max(1, Math.round(h0 * scale));
  const canvas = document.createElement('canvas');
  canvas.width = w; canvas.height = h;
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = '#fff'; ctx.fillRect(0, 0, w, h);          // PNGs with transparency -> white background
  ctx.drawImage(bmp, 0, 0, w, h);
  const blob = await new Promise(res=> canvas.toBlob(res, 'image/jpeg', COMMUNITY.quality));
  if(!blob) throw new Error('could not encode image');
  return {blob, width: w, height: h};
}

/* upload the photo + a "pending" row. Nothing shows publicly until you approve it. */
async function submitCommunityPhoto({file, caption, location, credit}){
  if(!communityEnabled()) throw new Error('community photos are not configured');
  if(!file || !/^image\//.test(file.type || '')) throw new Error('please choose an image file');
  const {blob, width, height} = await compressImage(file);
  const id = (window.crypto && crypto.randomUUID) ? crypto.randomUUID() : (Date.now().toString(36) + Math.random().toString(36).slice(2, 10));
  const d = new Date();
  const path = d.getFullYear() + '/' + String(d.getMonth() + 1).padStart(2, '0') + '/' + id + '.jpg';
  const base = COMMUNITY.url.replace(/\/$/, '');

  const up = await fetch(base + '/storage/v1/object/' + COMMUNITY.bucket + '/' + path, {
    method: 'POST',
    headers: communityHeaders({'Content-Type': 'image/jpeg', 'x-upsert': 'false'}),
    body: blob,
  });
  if(!up.ok) throw new Error('upload failed (' + up.status + ')');

  const row = await fetch(base + '/rest/v1/' + COMMUNITY.table, {
    method: 'POST',
    headers: communityHeaders({'Content-Type': 'application/json', Prefer: 'return=minimal'}),
    body: JSON.stringify({
      caption:  String(caption  || '').trim().slice(0, 300),
      location: String(location || '').trim().slice(0, 80),
      credit:   String(credit   || '').trim().slice(0, 60),
      image_path: path, width, height,
    }),
  });
  if(!row.ok) throw new Error('saving details failed (' + row.status + ')');
  return {path, width, height};
}


/* =====================================================================
   SUBMIT FORM  +  FACEBOOK UPDATES  (used by submit.html and updates.html)
   ===================================================================== */

/* "Submit Your Photograph" opens submit.html, which shows THIS Google Form.
   Google Forms → Send → "<>" (embed) tab, or just paste the normal form link
   (https://docs.google.com/forms/d/e/….../viewform). */
const PHOTO_FORM_URL = '';

/* updates.html — Facebook content.
   1) FB_PAGE_URL (optional): your Facebook PAGE link. Its latest posts then
      show automatically as a live feed:  'https://www.facebook.com/YourPage'
   2) fbPosts: add posts in either way (public posts only — Facebook's rule):
        a) paste the whole embed code that Facebook gives you (⋯ → Embed), in backticks:
             `<iframe src="https://www.facebook.com/plugins/post.php?href=…" width="500" height="770" …></iframe>`,
        b) or just the link:   {url:'https://www.facebook.com/YourPage/posts/123456789'}
           {url:'https://www.facebook.com/reel/1234567890/'}   {url:'…/watch/?v=1234567890', note:'optional text', h:700}
      The page rebuilds its own safe iframe from the link inside, so nothing else from the pasted code is used. */
const FB_PAGE_URL = '';
const fbPosts = [
  `<iframe src="https://www.facebook.com/plugins/post.php?href=https%3A%2F%2Fwww.facebook.com%2Fpermalink.php%3Fstory_fbid%3Dpfbid0Lkv9Fx5CS6qc8Aj1em2DaWAge6Nxc1969PFN99cKaQGxj6HgaCCHKZTZCUf7g1H7l%26id%3D61577470169743&show_text=true&width=500" width="500" height="770" style="border:none;overflow:hidden" scrolling="no" frameborder="0" allowfullscreen="true" allow="autoplay; clipboard-write; encrypted-media; picture-in-picture; web-share"></iframe>`,
  `<iframe src="https://www.facebook.com/plugins/post.php?href=https%3A%2F%2Fwww.facebook.com%2Fpermalink.php%3Fstory_fbid%3Dpfbid02pucAicTi8U2AZBy2vK57MkcLE6XG6Y913EjAsWd5d9aHAHjPAiTZBa2B12QbhXpfl%26id%3D61550292149139&show_text=true&width=500" width="500" height="703" style="border:none;overflow:hidden" scrolling="no" frameborder="0" allowfullscreen="true" allow="autoplay; clipboard-write; encrypted-media; picture-in-picture; web-share"></iframe>`,
  `<iframe src="https://www.facebook.com/plugins/post.php?href=https%3A%2F%2Fwww.facebook.com%2FSSBbengalipujaparban%2Fposts%2Fpfbid025KwT96m4rYcnv5YvdnrPnmtMU1kHqLv3B9MMf9n1JqwSjyATcLy2ZtkJ2sY6kfhtl&show_text=true&width=500" width="500" height="666" style="border:none;overflow:hidden" scrolling="no" frameborder="0" allowfullscreen="true" allow="autoplay; clipboard-write; encrypted-media; picture-in-picture; web-share"></iframe>`,
  // add the next post below this line (embed code in backticks, or {url:'…'})
];

const FB_HOSTS = /^https:\/\/((www|web|m)\.)?facebook\.com\/|^https:\/\/fb\.watch\//i;
function fbEmbedSrc(url, width){
  if(!FB_HOSTS.test(url || '')) return null;
  const href = encodeURIComponent(url);
  const w = Math.max(350, Math.min(750, Math.round(width || 500)));
  const isVideo = /\/(reel|reels|videos|watch)\b|fb\.watch/i.test(url);
  return isVideo
    ? {kind:/\/reels?\//i.test(url) ? 'reel' : 'video', src:`https://www.facebook.com/plugins/video.php?href=${href}&show_text=true&width=${w}`}
    : {kind:'post', src:`https://www.facebook.com/plugins/post.php?href=${href}&show_text=true&width=${w}`};
}
/* fbPosts[] entry -> {url, h, note}.  Accepts {url}, a plain link, or Facebook's pasted <iframe> embed code. */
function normalizeFbPost(entry){
  if(typeof entry === 'string'){
    const s = entry.trim();
    if(!/^<iframe/i.test(s)) return FB_HOSTS.test(s) ? {url:s} : null;
    const src = (s.match(/\ssrc=["']([^"']+)["']/i) || [])[1];
    const hh  = (s.match(/\sheight=["']?(\d{3,4})/i) || [])[1];
    if(!src) return null;
    try{
      const u = new URL(src.replace(/&amp;/g, '&'));
      if(!/(^|\.)facebook\.com$/i.test(u.hostname) || !/^\/plugins\/(post|video)\.php$/i.test(u.pathname)) return null;
      const href = u.searchParams.get('href');
      return href ? {url: href, h: hh ? Number(hh) : undefined} : null;
    }catch(e){ return null; }
  }
  return entry && entry.url ? entry : null;
}
function fbPageSrc(pageUrl){
  if(!FB_HOSTS.test(pageUrl || '')) return null;
  return `https://www.facebook.com/plugins/page.php?href=${encodeURIComponent(pageUrl)}&tabs=timeline&width=500&height=800&small_header=true&adapt_container_width=true&hide_cover=false&show_facepile=false`;
}
/* turn the share link into the embeddable Google Form link */
function googleFormEmbedURL(u){
  if(!/^https:\/\/(docs\.google\.com\/forms\/|forms\.gle\/)/i.test(u || '')) return null;
  if(/forms\.gle\//i.test(u)) return u;                       // short links cannot take ?embedded=true
  return u.includes('embedded=true') ? u : u + (u.includes('?') ? '&' : '?') + 'embedded=true';
}


/* ---------- render Facebook posts into any container (homepage + updates.html) ----------
   entries = fbPosts-style list, limit = max number to show. Returns how many were drawn. */
function renderFbPosts(container, entries, limit){
  /* 1) read + validate every entry first, so all cards can be given ONE common height */
  const list = [];
  (entries || []).forEach(raw=>{
    if(limit && list.length >= limit) return;
    const p = normalizeFbPost(raw);
    const probe = p && fbEmbedSrc(p.url);
    if(probe) list.push({p, probe});
  });
  if(!list.length) return 0;
  const tallest = Math.max(...list.map(x=> x.p.h || 600));      // tallest embed code you pasted (they were measured at 500px wide)

  /* 2) draw them, all with the same width and the same height */
  list.forEach(({p, probe})=>{
    const item = document.createElement('div');
    item.className = 'fb-item glass';
    item.innerHTML = (p.note ? `<p class="fb-note">${escapeHtml(p.note)}</p>` : '') +
      `<div class="fb-frame"><iframe class="${probe.kind}" title="Facebook ${probe.kind}" loading="lazy" allowfullscreen allow="autoplay; clipboard-write; encrypted-media; picture-in-picture; web-share"></iframe></div>` +
      `<a class="fb-open" href="${escapeHtml(p.url)}" target="_blank" rel="noopener">Facebook-এ খুলুন ↗</a>`;
    container.appendChild(item);
    const frame = item.querySelector('iframe');
    const colW = item.clientWidth - 28;
    frame.style.height = Math.round(tallest * Math.max(0.92, Math.min(1, colW / 500))) + 'px';
    /* ask Facebook for the width that fits this column (it only draws correctly at 350–750px) */
    frame.src = fbEmbedSrc(p.url, colW).src;
    if(colW < 350){                      // very narrow phone: draw at Facebook's minimum width, then shrink to fit
      const k = colW / 350, wrap = item.querySelector('.fb-frame');
      frame.style.width = '350px'; frame.style.maxWidth = 'none';
      frame.style.transformOrigin = '0 0'; frame.style.transform = `scale(${k})`;
      wrap.style.overflow = 'hidden'; wrap.style.height = Math.round(frame.offsetHeight * k) + 'px';
    }
  });
  return list.length;
}
/* live feed of a Facebook PAGE (FB_PAGE_URL) */
function renderFbPage(container, pageUrl){
  const src = fbPageSrc(pageUrl);
  if(!src) return false;
  const box = document.createElement('div');
  box.className = 'fb-page glass';
  box.innerHTML = `<iframe src="${src}" title="Facebook page timeline" loading="lazy" allow="encrypted-media; picture-in-picture; web-share"></iframe>`;
  container.appendChild(box);
  return true;
}


/* ---------- side-by-side scroller for Facebook posts ----------
   strip = the .fb-strip element; the ‹ › buttons are the .fb-arrow siblings inside its .fb-strip-wrap. */
function initFbStrip(strip){
  const wrap = strip.parentElement;
  const prev = wrap.querySelector('.fb-arrow.prev'), next = wrap.querySelector('.fb-arrow.next');
  let hint = wrap.querySelector('.fb-hint');
  if(!hint){
    hint = document.createElement('div');
    hint.className = 'fb-hint bn';
    hint.textContent = '← বামে-ডানে স্ক্রল / সোয়াইপ করুন →';
    wrap.appendChild(hint);
  }
  const step = ()=>{
    const first = strip.querySelector('.fb-item, .fb-page');
    return (first ? first.offsetWidth : strip.clientWidth * 0.8) + 22;
  };
  const sync = ()=>{
    const max = strip.scrollWidth - strip.clientWidth;
    const scrollable = max > 4;
    wrap.classList.toggle('scrollable', scrollable);
    if(prev) prev.disabled = strip.scrollLeft <= 4;
    if(next) next.disabled = strip.scrollLeft >= max - 4;
  };
  if(prev) prev.onclick = ()=> strip.scrollBy({left: -step(), behavior: 'smooth'});
  if(next) next.onclick = ()=> strip.scrollBy({left:  step(), behavior: 'smooth'});
  strip.addEventListener('scroll', sync, {passive:true});
  window.addEventListener('resize', sync);
  sync(); setTimeout(sync, 400); setTimeout(sync, 1500);
}
